// ============================================================
// Parse AI JSON Output — robust decoder with graceful error handling
// Input  : $input.first().json.output
// Output : success=true  -> parsed JSON
//          success=false -> structured error
// ============================================================

const rawInput = $input.first().json.output;

try {
  if (!rawInput || typeof rawInput !== 'string') {
    throw new Error('Input "output" tidak ditemukan atau bukan string.');
  }

  const decodeAndParse = (str) => {
    str = str.trim();

    // Remove wrapping quotes
    if (
      (str.startsWith('"') && str.endsWith('"')) ||
      (str.startsWith("'") && str.endsWith("'"))
    ) {
      str = str.slice(1, -1);
    }

    // Decode escaped chars
    str = str
      .replace(/\\\\n/g, '\n')
      .replace(/\\\\t/g, '\t')
      .replace(/\\\\r/g, '\r')
      .replace(/\\\\\"/g, '"')
      .replace(/\\\\\\\\/g, '\\');

    // Remove markdown code blocks
    str = str
      .replace(/^```json[\s]*/i, '')
      .replace(/^```[\s]*/i, '')
      .replace(/```[\s]*$/i, '');

    str = str.trim();

    try {
      return JSON.parse(str);
    } catch (e1) {
      const match = str.match(/\{[\s\S]*\}/);

      if (match) {
        try {
          return JSON.parse(match[0]);
        } catch (e2) {
          throw new Error(
            `Gagal parse JSON fallback: ${e2.message}`
          );
        }
      }

      throw new Error(
        `Tidak ditemukan blok JSON valid: ${e1.message}`
      );
    }
  };

  const parsed = decodeAndParse(rawInput);

  const webhookBody = $('Edit Fields').first().json;
  const inputReferenceImages = Array.isArray(webhookBody.reference_images)
    ? webhookBody.reference_images
    : [];

  const allowedReferenceIds = new Set(
    inputReferenceImages.map((ref) => ref.id)
  );

  const validStrengths = ["subtle", "normal", "prominent"];

  for (const step of parsed.steps || []) {
    step.image = step.image || {};

    const refs = Array.isArray(step.image.reference_images)
      ? step.image.reference_images
      : [];

    step.image.reference_images = refs.filter((id) => allowedReferenceIds.has(id));

    if (!step.image.reference_images.length) {
      step.image.reference_usage = "";
      step.image.reference_strength = "subtle";
    } else {
      step.image.reference_usage = String(step.image.reference_usage || "");
      step.image.reference_strength = validStrengths.includes(step.image.reference_strength)
        ? step.image.reference_strength
        : "normal";
    }
  }

  return [{
    json: {
      success: true,
      ...parsed
    }
  }];

} catch (error) {
  return [{
    json: {
      success: false,
      stage: "steps",
      error: error.message,
      raw_preview: rawInput
        ? rawInput.slice(0, 500)
        : null
    }
  }];
}
